function loadScript(src){window.__loaded=window.__loaded||{};return window.__loaded[src]||(window.__loaded[src]=new Promise((ok,no)=>{const sc=document.createElement('script');sc.src=src;sc.onload=ok;sc.onerror=no;document.head.append(sc);}));}
