async function supplyPoints(uf,cats){window.__supply=window.__supply||{};if(!window.ATLAS_SUPPLY_CHUNK)window.ATLAS_SUPPLY_CHUNK=(id,rows)=>{window.__supply[id]=rows;};await loadScript('assets/supply_chain/index.js');const chunks=(window.ATLAS_SUPPLY_INDEX||[]).filter(c=>c.uf===uf&&cats.includes(c.category));await Promise.all(chunks.map(c=>loadScript(c.path).catch(()=>{})));return chunks.flatMap(c=>window.__supply[c.id]||[]);}
async function cornPoints(uf,cats){window.__corn=window.__corn||{};if(!window.ATLAS_CORN_CHAIN_CHUNK)window.ATLAS_CORN_CHAIN_CHUNK=(id,d)=>{window.__corn[id]=d;};await loadScript('assets/corn_chain/index.js');const chunks=(window.ATLAS_CORN_CHAIN_INDEX||[]).filter(c=>c.uf===uf&&cats.includes(c.category)&&!/context/.test(c.id));await Promise.all(chunks.map(c=>loadScript(c.path).catch(()=>{})));return chunks.flatMap(c=>{const d=window.__corn[c.id];if(!d)return [];return d.rows.map(r=>{const o=Object.fromEntries(d.fields.map((f,i)=>[f,r[i]]));return {id:o.id,name:o.name,category:o.category,municipality:o.municipality,lat:o.lat,lon:o.lon,source:({conab:'CONAB',epe:'EPE',google:'Google Maps'})[o.source]||o.source,place:(o.reported_municipality||'')};});});}
function haversine(a,b,c,d){const R=6371,r=x=>x*Math.PI/180,dl=r(c-a),dn=r(d-b),h=Math.sin(dl/2)**2+Math.cos(r(a))*Math.cos(r(c))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h));}
