const USES={funders:[tr('Financiadores e gestores de programas','Funders and program managers'),tr('Onde testar um programa de recuperação de pastagens?','Where should a pasture recovery program be tested?'),tr('Procure municípios com muito pasto a recuperar e boas condições. Use a pressão ambiental para exigir proteção da floresta no mesmo programa.','Look for municipalities with much pasture to restore and good conditions. Use environmental pressure to require forest protection in the same program.')],government:[tr('Prefeituras e órgãos públicos','Local governments and public agencies'),tr('Onde concentrar as primeiras visitas técnicas?','Where should the first technical visits focus?'),tr('Veja onde o pasto mais precisa de cuidado e onde falta assistência técnica. Planeje as visitas junto com a fiscalização.','See where pasture most needs care and where technical advice is lacking. Plan visits together with enforcement.')],extension:[tr('Assistência técnica e cooperativas','Extension services and cooperatives'),tr('Que apoio os produtores precisam para melhorar o pasto?','What support do farmers need to improve pasture?'),tr('Escolha onde visitar primeiro. Leve o diagnóstico do município e confira o pasto no campo.','Choose where to visit first. Take the municipal diagnosis and check the pasture in the field.')],banks:[tr('Bancos','Banks'),tr('Onde o crédito pode recuperar pasto sem financiar desmatamento?','Where can credit restore pasture without funding clearing?'),tr('Compare a oportunidade com a pressão antes de emprestar. Onde a pressão é alta, peça garantias ambientais.','Compare opportunity with pressure before lending. Where pressure is high, ask for environmental safeguards.')],insurance:[tr('Seguradoras','Insurers'),tr('Que riscos pesam sobre a produção no município?','What risks weigh on production in the municipality?'),tr('Veja a frequência de seca e as condições locais. Elas ajudam a entender o risco da produção.','Check drought frequency and local conditions. They help explain production risk.')],industry:[tr('Frigoríficos e varejo','Slaughterhouses and retailers'),tr('Como apoiar fornecedores sem comprar de área desmatada?','How can buyers support suppliers without sourcing from cleared land?'),tr('Veja de onde vem e para onde vai o gado. Combine as compras com apoio à recuperação dos fornecedores.','See where cattle come from and where they go. Pair purchasing with support for suppliers’ pasture recovery.')],research:[tr('Sociedade civil, pesquisa e jornalismo','Civil society, research and journalism'),tr('O que os dados mostram sobre pecuária e floresta?','What do the data show about cattle and forests?'),tr('Compare municípios, acompanhe mudanças e investigue. Confira sempre a fonte e o ano de cada número.','Compare municipalities, track change and investigate. Always check the source and year of each number.')]};const aud=Object.entries(USES).map(([id,[name,q,use]])=>({id,name,q,use}));const nMun=5571;
