eps.push(episode(2,titles[1][1],'<span class="ep-head">'+tr('Quanto do pasto do Brasil cresce menos do que poderia?','How much of Brazil’s pasture grows less than it could?')+'</span>','<div class="play-controls"><label class="play-select">'+tr('Veja o Brasil ou um estado','See Brazil or one state')+'<select id="ab-scope"><option value="BR">'+tr('Brasil','Brazil')+'</option>'+Object.keys(STATES).sort().map(u=>'<option value="'+u+'">'+esc(STATES[u][1])+'</option>').join('')+'</select></label></div><div id="ab-problem-body"><p class="play-hint">'+tr('Somando os dados dos municípios.','Adding up municipal data.')+'</p></div>',tr('Pasto fraco produz pouco. Para criar mais gado, a saída comum é abrir novas áreas.','Weak pasture produces little. To raise more cattle, the usual answer is to clear new land.'),'ab-problem'));
