eps.push(episode(4,tr('O que tem de diferente','What makes it different'),tr('E daí? Por que mais uma ferramenta?','So what? Why another tool?'),paras([tr('Já existem bons mapas e painéis. Cada um olha uma parte do problema.','Good maps and dashboards already exist. Each one looks at one part of the problem.')])+'<p class="play-hint">'+tr('Toque em cada tipo de ferramenta.','Tap each kind of tool.')+'</p>'+chips('kind',kinds.map((k,i)=>[i,k[0]]),0)+'<div class="compare-card" aria-live="polite"></div><div class="atlas-adds"><strong>'+tr('O que só o Atlas junta','What only the Atlas brings together')+'</strong><p>'+tr('Em cada um dos municípios do Brasil, o Atlas mostra três coisas lado a lado:','For every municipality in Brazil, the Atlas shows three things side by side:')+'</p><ul><li>'+tr('onde o pasto pode produzir mais;','where pasture could produce more;')+'</li><li>'+tr('o que trava essa recuperação, como seca e falta de assistência;','what holds recovery back, such as drought and lack of advice;')+'</li><li>'+tr('onde a vegetação nativa está sob pressão.','where native vegetation is under pressure.')+'</li></ul><p>'+tr('E liga tudo à cadeia da carne, em linguagem simples, nas duas línguas.','It links everything to the beef supply chain, in plain language, in two languages.')+'</p></div>',tr('Ver as três coisas juntas mostra onde apoiar e onde proteger, ao mesmo tempo.','Seeing all three together shows where to support and where to protect, at the same time.'),'ab-diff'));
